// Premise benchmark gate (#570). Compares a benchmark run
// (bench-results/results.json, written by benchmarks/run.ts) with the
// committed baseline benchmarks/baseline.json and fails the job when
//   1. the run is missing or a selected suite has no results;
//   2. regression: for a suite, Elara's hit@5 or mean tokens-to-gold is
//      worse than the reference baseline by more than the tolerance below.
//      On a pull request the reference is the BASE commit's baseline (when
//      it has the same fingerprint), so editing the baseline in the PR
//      cannot hide a regression;
//   3. stale baseline: the PR's baseline does not match the run within the
//      tolerance in either direction (an improvement must be recorded in the
//      same PR), its fingerprint differs (questions or policy config
//      changed), its index outcome differs, or a selected suite has no entry.
// It writes the delta table (every metric, Elara and grep) to the job
// summary and to bench-results/gate.md.
//
// Tolerances come from two runs of the same commit (noise) plus a margin;
// see benchmarks/README.md "Thresholds". They live here, not in the
// baseline, because the workflow runs the base commit's copy of this file on
// pull requests: a PR cannot loosen the gate it is judged by.
//
// Plain Node, no dependencies, one file (it is copied alone to a temp dir).
//
//   node .github/scripts/bench-gate.mjs [--results bench-results/results.json] [--baseline benchmarks/baseline.json] [--base-baseline <file>]
//   node .github/scripts/bench-gate.mjs --write-baseline bench-results/results.json [--baseline benchmarks/baseline.json]
//   node .github/scripts/bench-gate.mjs --compare a/results.json b/results.json

import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'

/**
 * hit5Questions: questions whose hit@5 may flip before a change counts
 * (hit@5 tolerance = hit5Questions / questions of the suite).
 * tokensRelative: relative change of mean tokens-to-gold that counts.
 */
export const TOLERANCE = { hit5Questions: 1, tokensRelative: 0.1 }

/** Metrics the gate acts on (Elara policy); the rest are reported only. */
export const GATED = ['hit5', 'tokensToGold']

/** Aggregate fields, in table order; higher is better unless listed in LOWER_IS_BETTER. */
export const METRICS = [
  'hit1',
  'hit5',
  'hit10',
  'mrr',
  'ndcg10',
  'goldReached',
  'tokensToGold',
  'tokensToGoldMedian',
  'callsToGold',
  'linePrecision',
  'lineRecall',
  'tokens',
  'calls',
  'msMedian',
]
const LOWER_IS_BETTER = new Set(['tokensToGold', 'tokensToGoldMedian', 'callsToGold', 'tokens', 'calls', 'msMedian'])

/** Baseline entries of a run: aggregates plus each question's (rank, tokens-to-gold). */
export function toBaseline(results, previous = { suites: {} }) {
  const suites = { ...previous.suites }
  for (const [name, s] of Object.entries(results.suites)) {
    suites[name] = {
      fingerprint: s.fingerprint,
      commit: results.commit,
      run: results.runUrl,
      questions: s.questions,
      index: s.index.outcome,
      elara: s.aggregate.elara,
      grep: s.aggregate.grep,
      perQuestion: Object.fromEntries(
        s.perQuestion.map((q) => [q.id, { elara: [q.elara.rank, q.elara.tokensToGold], grep: [q.grep.rank, q.grep.tokensToGold] }]),
      ),
    }
  }
  return {
    note: 'Premise benchmark baseline. Generated by `node .github/scripts/bench-gate.mjs --write-baseline <results.json>`; never edit numbers by hand. Method: benchmarks/README.md.',
    suites: Object.fromEntries(Object.entries(suites).sort(([a], [b]) => a.localeCompare(b))),
  }
}

/**
 * How a gated metric moved from `ref` to `cur`: 'worse', 'better' or 'same'
 * (within tolerance). hit5 is a fraction of `questions`.
 */
export function movement(metric, ref, cur, questions) {
  if (metric === 'hit5') {
    const tol = TOLERANCE.hit5Questions / questions + 1e-9
    return cur < ref - tol ? 'worse' : cur > ref + tol ? 'better' : 'same'
  }
  if (metric === 'tokensToGold') {
    const tol = ref * TOLERANCE.tokensRelative
    return cur > ref + tol ? 'worse' : cur < ref - tol ? 'better' : 'same'
  }
  throw new Error(`metric ${metric} is not gated`)
}

/**
 * The verdict. `baseline` = the PR's (or the branch's) baseline file,
 * `baseBaseline` = the base commit's on a pull request (null otherwise or
 * when the base has none).
 */
export function evaluate({ results, baseline, baseBaseline = null }) {
  const failures = []
  const notes = []
  const suites = []
  if (!results) return { ok: false, failures: ['the benchmark wrote no bench-results/results.json (harness failure: see the run step log)'], notes, suites }
  for (const name of results.selected) {
    const run = results.suites[name]
    if (!run) {
      failures.push(`${name}: selected but no results`)
      continue
    }
    const own = baseline?.suites?.[name]
    const base = baseBaseline?.suites?.[name]
    const row = { name, run, own, ref: null, refLabel: null, verdicts: {} }
    suites.push(row)
    if (!own) {
      failures.push(`${name}: no entry in benchmarks/baseline.json; add it from this run (--write-baseline)`)
      continue
    }
    if (own.fingerprint !== run.fingerprint) {
      failures.push(`${name}: baseline fingerprint ${own.fingerprint} != run ${run.fingerprint} (questions or policy config changed); regenerate the entry from this run`)
      continue
    }
    if (own.index !== run.index.outcome) {
      failures.push(`${name}: index outcome "${run.index.outcome}" but the baseline was measured on "${own.index}"`)
    }
    // Regression reference: the base commit's numbers when comparable, else the PR's.
    const ref = base && base.fingerprint === run.fingerprint ? base : own
    row.ref = ref
    row.refLabel = ref === base ? 'base baseline' : 'baseline'
    if (base && ref !== base) notes.push(`${name}: the base commit's baseline has another fingerprint; regressions are judged against this PR's baseline`)
    for (const metric of GATED) {
      const cur = run.aggregate.elara[metric]
      const vsRef = movement(metric, ref.elara[metric], cur, run.questions)
      const vsOwn = movement(metric, own.elara[metric], cur, run.questions)
      row.verdicts[metric] = vsRef === 'worse' ? 'regression' : vsOwn !== 'same' ? 'stale' : 'ok'
      if (vsRef === 'worse') {
        failures.push(`${name}: regression, Elara ${metric} ${ref.elara[metric]} -> ${cur} (${row.refLabel}; tolerance ${describeTolerance(metric, run.questions)})`)
      } else if (vsOwn !== 'same') {
        failures.push(`${name}: stale baseline, Elara ${metric} is ${vsOwn} than benchmarks/baseline.json (${own.elara[metric]} -> ${cur}); record this run with --write-baseline in this PR`)
      }
    }
  }
  return { ok: failures.length === 0, failures, notes, suites }
}

function describeTolerance(metric, questions) {
  return metric === 'hit5' ? `${TOLERANCE.hit5Questions} of ${questions} questions` : `${TOLERANCE.tokensRelative * 100} %`
}

function fmt(v) {
  if (v === undefined || v === null) return '-'
  return Number.isInteger(v) ? String(v) : v.toFixed(4).replace(/0+$/, '').replace(/\.$/, '')
}

function delta(metric, ref, cur) {
  if (ref === undefined || ref === null || cur === undefined) return '-'
  const d = cur - ref
  if (Math.abs(d) < 1e-9) return '0'
  const better = LOWER_IS_BETTER.has(metric) ? d < 0 : d > 0
  return `${d > 0 ? '+' : ''}${fmt(Math.round(d * 10_000) / 10_000)} ${better ? '(better)' : '(worse)'}`
}

/** Per-question differences between a baseline entry and a run (Elara rank or tokens-to-gold). */
export function questionChanges(own, run) {
  if (!own?.perQuestion) return []
  const out = []
  for (const q of run.perQuestion) {
    const was = own.perQuestion[q.id]
    if (!was) continue
    const [rank, tokens] = was.elara
    if (rank !== q.elara.rank || tokens !== q.elara.tokensToGold) {
      out.push(`${q.id}: rank ${rank ?? 'miss'} -> ${q.elara.rank ?? 'miss'}, tokens-to-gold ${tokens ?? 'miss'} -> ${q.elara.tokensToGold ?? 'miss'}`)
    }
  }
  return out
}

export function render(report, results) {
  const md = ['# Premise benchmark gate', '']
  md.push(report.ok ? '**Pass.**' : '**Fail.**', '')
  if (results) md.push(`Run ${results.runUrl ?? '(local)'}, commit ${results.commit ?? '(local)'}, suites ${results.selected.join(', ')}.`, '')
  if (report.failures.length) md.push('Failures:', '', ...report.failures.map((f) => `- ${f}`), '')
  if (report.notes.length) md.push(...report.notes.map((n) => `- ${n}`), '')
  for (const row of report.suites) {
    const { run, own, ref } = row
    md.push(`## ${row.name}: ${run.questions} questions`, '')
    md.push(`Index: ${run.index.outcome}, ${run.index.files} files, ${run.index.symbols} symbols, ${Math.round(run.index.ms / 1000)} s.`, '')
    const refCol = ref && ref !== own ? ' | base baseline' : ''
    md.push(`| metric | baseline${refCol} | Elara (this run) | Δ vs baseline | grep (this run) | gate |`)
    md.push(`|---|---|${refCol ? '---|' : ''}---|---|---|---|`)
    for (const m of METRICS) {
      const ownV = own?.elara?.[m]
      const refV = refCol ? ` | ${fmt(ref.elara[m])}` : ''
      md.push(`| ${m} | ${fmt(ownV)}${refV} | ${fmt(run.aggregate.elara[m])} | ${delta(m, ownV, run.aggregate.elara[m])} | ${fmt(run.aggregate.grep[m])} | ${row.verdicts[m] ?? ''} |`)
    }
    md.push('')
    const changes = questionChanges(own, run)
    if (changes.length) md.push(`<details><summary>${changes.length} questions changed (Elara)</summary>`, '', ...changes.map((c) => `- ${c}`), '', '</details>', '')
  }
  md.push(
    `Gated: Elara ${GATED.join(', ')}. Tolerance: hit@5 ${TOLERANCE.hit5Questions} question per suite, tokens-to-gold ${TOLERANCE.tokensRelative * 100} %. A miss costs ${results?.missCost?.tokens ?? '?'} tokens and ${results?.missCost?.calls ?? '?'} calls. Method: benchmarks/README.md.`,
  )
  return md.join('\n')
}

/** Two runs of the same commit side by side: the noise the tolerances must exceed. */
export function compare(a, b) {
  const md = ['# Benchmark noise: two runs compared', '', `A: ${a.runUrl ?? '(local)'}`, `B: ${b.runUrl ?? '(local)'}`, '']
  for (const name of a.selected) {
    const sa = a.suites[name]
    const sb = b.suites[name]
    if (!sb) continue
    md.push(`## ${name}`, '', '| metric | elara A | elara B | Δ | grep A | grep B |', '|---|---|---|---|---|---|')
    for (const m of METRICS) {
      md.push(`| ${m} | ${fmt(sa.aggregate.elara[m])} | ${fmt(sb.aggregate.elara[m])} | ${delta(m, sa.aggregate.elara[m], sb.aggregate.elara[m])} | ${fmt(sa.aggregate.grep[m])} | ${fmt(sb.aggregate.grep[m])} |`)
    }
    const changes = questionChanges(toBaseline({ ...a, suites: { [name]: sa } }).suites[name], sb)
    md.push('', `Questions whose Elara rank or tokens-to-gold differ: ${changes.length}`, ...changes.map((c) => `- ${c}`), '')
  }
  return md.join('\n')
}

function readJson(file) {
  return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : null
}

function main() {
  const args = process.argv.slice(2)
  const opt = (name, fallback) => {
    const i = args.indexOf(name)
    return i >= 0 ? args[i + 1] : fallback
  }
  const baselineFile = opt('--baseline', 'benchmarks/baseline.json')
  if (args.includes('--write-baseline')) {
    const results = readJson(opt('--write-baseline'))
    if (!results) throw new Error('--write-baseline needs a results.json')
    writeFileSync(baselineFile, `${JSON.stringify(toBaseline(results, readJson(baselineFile) ?? { suites: {} }), null, 2)}\n`)
    console.log(`wrote ${baselineFile} (${Object.keys(results.suites).join(', ')})`)
    return
  }
  if (args.includes('--compare')) {
    const i = args.indexOf('--compare')
    console.log(compare(readJson(args[i + 1]), readJson(args[i + 2])))
    return
  }
  const resultsFile = opt('--results', 'bench-results/results.json')
  const results = readJson(resultsFile)
  const baseBaselineFile = opt('--base-baseline')
  const report = evaluate({ results, baseline: readJson(baselineFile), baseBaseline: baseBaselineFile ? readJson(baseBaselineFile) : null })
  const markdown = render(report, results)
  console.log(markdown)
  mkdirSync(dirname(resultsFile), { recursive: true })
  writeFileSync(join(dirname(resultsFile), 'gate.md'), markdown)
  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${markdown}\n`)
  process.exitCode = report.ok ? 0 : 1
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) main()
